/**
 * PayPal client construction.
 *
 * Sandbox by default. Credentials come from the environment and are never
 * committed; `.env.example` lists what is needed.
 *
 * Note for anyone reading this alongside the APIMatic write-up: the PayPal
 * Server SDK is itself generated by APIMatic (its source headers say so), which
 * is why the context plugin can describe its exact client shape, controller
 * naming and error types rather than guessing from the REST docs.
 */
import { Client, Environment, LogLevel } from '@paypal/paypal-server-sdk';

export interface PayPalEnv {
  clientId: string;
  clientSecret: string;
  live: boolean;
}

export function readPayPalEnv(): PayPalEnv | null {
  const clientId = process.env.PAYPAL_CLIENT_ID;
  const clientSecret = process.env.PAYPAL_CLIENT_SECRET;
  if (!clientId || !clientSecret) return null;
  return { clientId, clientSecret, live: process.env.PAYPAL_ENV === 'live' };
}

export function makeClient(env: PayPalEnv): Client {
  return new Client({
    clientCredentialsAuthCredentials: {
      oAuthClientId: env.clientId,
      oAuthClientSecret: env.clientSecret,
    },
    environment: env.live ? Environment.Production : Environment.Sandbox,
    timeout: 20000,
    logging: {
      logLevel: LogLevel.Error,
      logRequest: { logBody: false },
      logResponse: { logHeaders: false },
    },
  });
}
